// Make the agent's inputs safe and predictable before touching the database
const j = $json;

// reference: like T1000531 or TR000001. Fix small formatting problems.
let reference = String(j.reference ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
if (/^\d+$/.test(reference)) reference = 'T' + reference;       // "1000531" becomes "T1000531"
if (!/^(T|TR)\d+$/.test(reference)) reference = '';             // anything else is invalid

// reason: turn the caller's words into one of six values
const r = String(j.reason ?? '').toLowerCase();
let reason = '';
if (/not me|unauthori|didn.?t make|don.?t recogni|never made|fraud|stolen|hack/.test(r)) reason = 'fraud';
else if (/twice|double|duplicate|two times|charged again/.test(r)) reason = 'duplicate';
else if (/wrong amount|overcharg|too much|more than|incorrect amount|wrong price/.test(r)) reason = 'wrong_amount';
else if (/never (received|got|arrived)|didn.?t (receive|get|arrive)|not (received|delivered)|never delivered/.test(r)) reason = 'not_received';
else if (/cancel|subscription|refund/.test(r)) reason = 'cancelled';
else if (r.trim()) reason = 'other';

// confirmed: only an explicit yes counts
const yesWords = ['yes', 'y', 'true', 'confirmed', '1'];
const confirmed = yesWords.includes(String(j.confirmed ?? '').trim().toLowerCase()) ? 'yes' : '';

return {
  json: {
    customer_id: String(j.customer_id ?? '').replace(/\D/g, ''),
    security_answer: String(j.security_answer ?? ''),
    reference,
    reason,
    confirmed,
  },
};

// Turn the result into clear instructions for the agent
const j = $json;
const input = $('Clean inputs').item.json;

if (!j || !j.customer_id) {
  return { json: { result: 'NOT VERIFIED. The customer ID or security answer did not match. Do not take any action. Ask the caller to verify again.' } };
}

// Helpers
const obj = v => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v) || null;
const t = obj(j.txn);
const existing = obj(j.existing);
const inserted = obj(j.inserted);
const money = n => Math.abs(Number(n)).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const day = d => new Date(String(d).slice(0, 19) + 'Z').toLocaleDateString('en-US', { month: 'long', day: 'numeric', timeZone: 'UTC' });
const fmt = d => d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
const addBusinessDays = (start, n) => {
  const d = new Date(start);
  let added = 0;
  while (added < n) {
    d.setDate(d.getDate() + 1);
    const w = d.getDay();
    if (w !== 0 && w !== 6) added++;
  }
  return d;
};
const addDays = (start, n) => { const d = new Date(start); d.setDate(d.getDate() + n); return d; };
const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
const reasonText = {
  duplicate: 'a duplicate charge',
  wrong_amount: 'a wrong amount',
  not_received: 'goods or services not received',
  cancelled: 'a charge after cancelling',
  other: 'a problem with the charge',
};
const today = new Date();
let result;

if (!input.reference) {
  result = 'NEED THE TRANSACTION. No valid transaction reference was given. Use get_transactions to find the charge the caller means (it lists a reference for each transaction), confirm the merchant, date, and amount with the caller, then use dispute_transaction with that reference.';
} else if (!t) {
  result = `NO TRANSACTION FOUND. No transaction with reference ${input.reference} was found on this customer's accounts. Use get_transactions to find the right charge and its reference, then try again.`;
} else {
  const what = `the ${money(t.amount)} charge from ${t.description} on ${day(t.txn_time)}`;

  if (inserted) {
    // The dispute was opened
    const opened = new Date(inserted.created_at);
    const credit = Math.abs(Number(t.amount)) > 25
      ? ` A temporary credit of ${money(t.amount)} is usually added to the account by ${fmt(addBusinessDays(opened, 10))} while the case is investigated.`
      : ' Disputes of 25 dollars or less do not get a temporary credit.';
    result = `DONE. Dispute number ${inserted.dispute_id} has been opened for ${what}, for ${reasonText[input.reason]}.${credit} Most disputes are resolved by ${fmt(addDays(opened, 45))}. The customer will be notified of the result. Tell the caller the dispute number and these dates in two or three short sentences.`;
  } else if (existing) {
    result = `ALREADY DISPUTED. ${cap(what)} already has dispute number ${existing.dispute_id}, opened on ${fmt(new Date(existing.created_at))}, status ${existing.status}. Do not open another one. Tell the caller this.`;
  } else if (input.reason === 'fraud') {
    result = `THIS IS FRAUD, NOT A DISPUTE. The caller says they did not make ${what}. Do not open a dispute. Instead, offer to block the card right away with block_card, then follow the fraud steps.`;
  } else if (Number(t.amount) >= 0) {
    result = `CANNOT DISPUTE. ${cap(what.replace('charge', 'payment'))} is money coming in, not a charge. There is nothing to dispute.`;
  } else if (t.channel !== 'card') {
    result = `CANNOT DISPUTE. Only card payments can be disputed. ${cap(what)} is a ${t.channel.replace('_', ' ')}. A specialist can help with this kind of problem.`;
  } else if (t.status === 'pending') {
    result = `WAIT FIRST. ${cap(what)} is still pending, not final. Pending charges, especially duplicates, often drop off by themselves within 3 business days. Tell the caller to check again after ${fmt(addBusinessDays(today, 3))}, and to call back if it is still there once it posts.`;
  } else if (Number(t.age_days) > 60) {
    result = `TOO LATE TO DISPUTE. ${cap(what)} was ${t.age_days} days ago. Disputes must be raised within 60 days of the transaction. A specialist can help review it.`;
  } else if (!input.reason) {
    result = `NEED A REASON. ${cap(what)} can be disputed. Ask the caller what went wrong: charged twice, wrong amount, never received the goods or service, or charged after cancelling. Then use dispute_transaction again with their reason.`;
  } else {
    result = `NOT DONE YET. Ask the caller to confirm: "Just to confirm, you'd like to dispute ${what}, because of ${reasonText[input.reason]}?" Only if they clearly say yes, use dispute_transaction again with confirmed set to yes.`;
  }
}

return { json: { result } };
